"use strict";(globalThis.webpackChunkgrc||=[]).push([[83490],{12404(e){e.exports=JSON.parse('{"citeKey":"chanchio1998memoryspace","slug":"chanchio-1998-memory-space-d612","title":"Memory Space Representation for Heterogeneous Network Process Migration","authors":["K. Chanchio","X.-H. Sun"],"venue":"The 12th International Parallel Processing Symposium","type":"Conference","entryType":"inproceedings","date":"March, 1998","year":1998,"era":"archive","month":3,"doi":"10.1109/ipps.1998.670020","abstract":"A major difficulty of heterogeneous process migration is how to collect advanced dynamic data-structures, trans- form them into machine independent form, and restor them appropriately in a different hardware and software environ- ment. In this study we introduce a data model, the Mem- ory Space Representation (MSR) model, to recognize com- plex data structures in program address spaces. Support- ing mechanisms of the MSR model are also developed for collecting program data structures and restoring them in a heterogeneous environment. The MSR design has been im- plemented under a prototype heterogeneous process migra- tion environment. Pointer-intensive programs with function and recursion calls are tested. Experimental results confirm that the newly proposed design is feasible and effective for heterogeneous network process migration.","hasAbstract":true,"lede":"In this study we introduce a data model, the Mem- ory Space Representation (MSR) model, to recognize com- plex data structures in program address spaces.","links":{"pdf":"https://grc.iit.edu/papers/1998/chanchio-1998-memory-space-d612.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);